let method = $json.method;
if (!method) {
  method = $json.headers?.[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// ── Parse & Validate Form Body ──────────────────────────────

const body = $json.body;
if (!body || typeof body !== 'object') throw new Error('400: Missing body');

const flexDates = body.flexDates === 'yes' || body.flexDates === true;
const required = flexDates ? ['departure','destination'] : ['departure','destination','startDate','endDate'];
const missing = required.filter(k => !body[k] || String(body[k]).trim() === '');
if (missing.length > 0) throw new Error(`400: Missing: ${missing.join(', ')}`);

if (!flexDates) {
  const s = new Date(body.startDate), e = new Date(body.endDate);
  if (isNaN(s) || isNaN(e)) throw new Error('400: Invalid dates');
  if (e < s) throw new Error('400: endDate must be after startDate');
}

const safeArray = v => Array.isArray(v) ? v : (v ? [v] : []);
const normaliseAge = arr => arr.map(v => v === 'Adults' ? 'Adults_20_39' : v);

return [{ json: {
  departure:          body.departure.trim(),
  destination:        body.destination.trim(),
  startDate:          (body.startDate || '').trim(),
  endDate:            (body.endDate   || '').trim(),
  flexDates,
  tripType:           body.tripType           || 'Not specified',
  travelPace:         body.travelPace         || 'Balanced',
  budgetTier:         body.budgetTier         || 'Standard',
  dayActivity:        safeArray(body.dayActivity),
  nightActivity:      safeArray(body.nightActivity),
  groupSize:          body.groupSize          || '1',
  ageRange:           normaliseAge(safeArray(body.ageRange)),
  budget:             body.budget             || '0',
  email:              (body.email || '').trim(),
  accommodationType:  body.accommodationType  || '',
  amenities:          safeArray(body.amenities),
  starRating:         body.starRating         || '',
  flightPreference:   body.flightPreference   || '',
  transferNeeds:      body.transferNeeds      || '',
  specialOccasion:    body.specialOccasion    || '',
  anniversaryUpgrade: body.anniversaryUpgrade === 'yes' || body.anniversaryUpgrade === true,
  dietaryNeeds:       body.dietaryNeeds       || '',
  accessibilityNeeds: body.accessibilityNeeds || '',
}}];

// ── Build AI Prompt ──────────────────────────────────────────

const {
  departure, destination, startDate, endDate, flexDates,
  tripType, travelPace, budgetTier,
  dayActivity, nightActivity, groupSize, ageRange,
  budget, email, accommodationType, amenities, starRating,
  flightPreference, transferNeeds, specialOccasion,
  anniversaryUpgrade, dietaryNeeds, accessibilityNeeds
} = $json;

const fmt = v => Array.isArray(v) && v.length ? v.join(', ') : 'No preference';

const paceLabel = {
  Relaxed:  'Relaxed & slow (max 2 activities/day, plenty of downtime)',
  Balanced: 'Balanced (3–4 activities/day, mix of active and leisure)',
  Active:   'Packed & active (full days morning to evening)',
}[travelPace] || travelPace;

const dateLine = flexDates
  ? 'Flexible — suggest optimal travel window'
  : `${startDate} to ${endDate}`;

const tierLabel = {
  Economy:  'Economy — budget-conscious, best value for money',
  Standard: 'Standard — comfortable mid-range with quality experiences',
  Elite:    'Elite — luxury, premium, no compromises',
}[budgetTier] || budgetTier;

const prompt = `Please create a complete tropical trip itinerary with the following details:

- Departure: ${departure}
- Destination: ${destination}
- Dates: ${dateLine}
- Trip Type: ${tripType}
- Travel Pace: ${paceLabel}
- Budget Tier: ${tierLabel}
- Total Budget: $${budget} USD
- Group Size: ${groupSize}
- Age Ranges: ${fmt(ageRange)}
- Day Activities: ${fmt(dayActivity)}
- Night Activities: ${fmt(nightActivity)}
- Accommodation Type: ${accommodationType || 'No preference'}
- Resort Amenities: ${fmt(amenities)}
- Star Rating: ${starRating || 'No preference'}
- Flight Preference: ${flightPreference || 'No preference'}
- Airport Transfer: ${transferNeeds || 'No preference'}
- Dietary Needs: ${dietaryNeeds || 'None'}
- Accessibility: ${accessibilityNeeds || 'None'}
- Special Occasion: ${specialOccasion || 'None'}
- Surprise Romance Upgrade: ${anniversaryUpgrade ? 'YES' : 'No'}

Please follow all formatting and content rules from the system prompt exactly.`;

return [{ json: {
  departure, destination, startDate, endDate, flexDates,
  tripType, travelPace, budgetTier, dayActivity, nightActivity,
  groupSize, ageRange, budget, email,
  accommodationType, amenities, starRating,
  flightPreference, transferNeeds, specialOccasion,
  anniversaryUpgrade, dietaryNeeds, accessibilityNeeds,
  prompt
}}];

// ── Format AI Output to HTML ────────────────────────────────

const rawContent = $node['OpenAI'].json?.message?.content;
if (!rawContent || rawContent.trim() === '') {
  const reason = $node['OpenAI'].json?.message?.finish_reason || 'unknown';
  throw new Error(`OpenAI empty content. Finish reason: ${reason}`);
}

// Pre-process: strip markdown fences, convert **bold** and ### headings
let raw = rawContent
  .replace(/```[\w]*\n?/g, '').replace(/```/g, '')
  .replace(/\*\*([^*\n]+)\*\*/g, '<strong style="color:#023e8a">$1</strong>')
  .replace(/^#{1,3}\s+(.+)$/gm, '$1:')
  .replace(/\r\n/g, '\n')
  .trim();

const HS  = 'font-size:16px;color:#023e8a;display:block;margin:22px 0 8px;font-weight:700;border-bottom:2px solid #eaf4fb;padding-bottom:4px;';
const HSS = 'font-size:14px;color:#023e8a;display:block;margin:14px 0 5px;font-weight:600;';
const CELL = 'border:1px solid #e2e8f0;padding:10px 14px;font-size:14px;';
const BCELL = 'border:1px solid #e2e8f0;padding:10px 14px;font-size:14px;background:#eaf4fb;font-weight:700;color:#023e8a;';

const lines = raw.split('\n');
let html = '';
let inCost = false, inSchedule = false;
let costRows = [], schedLines = [];

const flushCost = () => {
  if (!costRows.length) return '';
  const h = `<div style="overflow-x:auto;margin:12px 0"><table style="width:100%;border-collapse:collapse;font-size:0.9rem">
    <thead><tr>
      <th style="text-align:left;padding:9px 14px;background:#f1f5f9;border:1px solid #e2e8f0;color:#64748b;font-size:0.75rem;text-transform:uppercase;letter-spacing:.05em">Category</th>
      <th style="text-align:right;padding:9px 14px;background:#f1f5f9;border:1px solid #e2e8f0;color:#64748b;font-size:0.75rem;text-transform:uppercase;letter-spacing:.05em">Estimate</th>
    </tr></thead><tbody>${costRows.splice(0).join('')}</tbody></table></div>`;
  return h;
};

const flushSchedule = lines => {
  let o = `<strong style="${HS}">Daily Schedule:</strong>`;
  const joined = lines.join('\n');
  const days = joined.split(/(?=<strong>Day \d+:)/);
  for (const block of days) {
    if (!block.trim()) continue;
    const blines = block.split('\n').map(l => {
      const t = l.trim();
      if (!t) return '';
      if (t.startsWith('<strong>')) return `<div style="margin:10px 0 4px;">${t}</div>`;
      if (t.startsWith('- ')) return `<div style="padding-left:1.2em;margin:3px 0;color:#374151;">• ${t.slice(2)}</div>`;
      return `<div style="padding-left:1.2em;margin:3px 0;color:#374151;">${t}</div>`;
    });
    o += blines.join('');
  }
  return o + '<div style="margin:8px 0"></div>';
};

for (const raw of lines) {
  const line = raw.trim();

  if (!line) {
    if (inCost) { html += flushCost(); inCost = false; }
    else if (inSchedule) { html += flushSchedule(schedLines); inSchedule = false; schedLines = []; }
    else html += '<div style="margin:6px 0"></div>';
    continue;
  }

  const lower = line.toLowerCase();

  // Daily Schedule section
  if (lower.startsWith('daily schedule:')) {
    if (inCost) { html += flushCost(); inCost = false; }
    inSchedule = true; schedLines = []; continue;
  }
  if (inSchedule) { schedLines.push(line); continue; }

  // Cost Summary section
  if (lower.startsWith('cost summary:')) {
    if (inCost) html += flushCost();
    html += `<strong style="${HS}">Cost Summary:</strong>`;
    inCost = true; costRows = []; continue;
  }
  if (inCost) {
    if (line.includes('\t')) {
      const [cat, cost] = line.split('\t').map(s => s.replace(/<[^>]+>/g,'').trim());
      const isBold = /^(total|remaining)/i.test(cat);
      const s = isBold ? BCELL : CELL;
      costRows.push(`<tr><td style="${s}">${cat}</td><td style="${s};text-align:right;">${cost||''}</td></tr>`);
      continue;
    }
    html += flushCost(); inCost = false;
  }

  // Section headings — end with colon, no inner HTML tags or bullet prefix
  if (line.endsWith(':') && !line.startsWith('-') && !line.startsWith('•') && !line.includes('<a ')) {
    // Major vs minor headings
    const isMajor = /^(Flight Options|Accommodation|Daily Schedule|Must-Visit|Dining Guide|Estimated Food|Cost Summary|Travel Tips)/i.test(line);
    html += `<strong style="${isMajor ? HS : HSS}">${line}</strong>`;
    continue;
  }

  // Bullet points — preserve any embedded <a href> links
  if (line.startsWith('- ') || line.startsWith('• ')) {
    const text = line.slice(2);
    html += `<div style="display:flex;align-items:flex-start;gap:8px;padding:4px 0 4px 4px;border-bottom:1px solid #f1f5f9;">
      <span style="color:#0077b6;font-weight:700;flex-shrink:0;margin-top:1px;">•</span>
      <span style="color:#374151;line-height:1.6;">${text}</span>
    </div>`;
    continue;
  }

  // Everything else (plain lines, day labels already have <strong>)
  html += `<div style="margin:4px 0;color:#374151;line-height:1.6;">${line}</div>`;
}

// Flush at end
if (inCost) html += flushCost();
if (inSchedule) html += flushSchedule(schedLines);

// Fallback cost table
if (!html.toLowerCase().includes('cost summary:')) {
  const budget = $json.budget || '0';
  html += `<strong style="${HS}">Cost Summary:</strong>
    <div style="overflow-x:auto;margin:12px 0"><table style="width:100%;border-collapse:collapse;font-size:0.9rem"><tbody>
    <tr><td style="${CELL}">Flights</td><td style="${CELL};text-align:right;">$0</td></tr>
    <tr><td style="${CELL}">Accommodation</td><td style="${CELL};text-align:right;">$0</td></tr>
    <tr><td style="${CELL}">Activities</td><td style="${CELL};text-align:right;">$0</td></tr>
    <tr><td style="${CELL}">Food</td><td style="${CELL};text-align:right;">$0</td></tr>
    <tr><td style="${BCELL}">Total</td><td style="${BCELL};text-align:right;">$0</td></tr>
    <tr><td style="${BCELL}">Remaining Budget</td><td style="${BCELL};text-align:right;">$${budget}</td></tr>
    </tbody></table></div>`;
}

return [{ json: { ...$json, itinerary: html } }];

// ── Build email wrapper & resolve session ────────────────────

const destination   = $json.destination   || 'Your Destination';
const departure     = $json.departure     || 'Not specified';
const flexDates     = $json.flexDates     || false;
const travelDates   = flexDates ? 'Flexible dates' : `${$json.startDate||'N/A'} to ${$json.endDate||'N/A'}`;
const budget        = $json.budget        || 'N/A';
const groupSize     = $json.groupSize     || 'N/A';
const tripType      = $json.tripType      || 'N/A';
const travelPace    = $json.travelPace    || '';
const budgetTier    = $json.budgetTier    || 'Standard';
const specialOccasion   = $json.specialOccasion    || '';
const anniversaryUpgrade = $json.anniversaryUpgrade || false;
const dietaryNeeds  = $json.dietaryNeeds  || '';
const itineraryContent = $json.itinerary  || 'Itinerary details not available.';

const tierBadge = { Economy:'🟢 Economy', Standard:'🔵 Standard', Elite:'⭐ Elite' }[budgetTier] || budgetTier;
const paceLabel = { Relaxed:'🌅 Relaxed', Balanced:'🌊 Balanced', Active:'🏄 Active' }[travelPace] || travelPace;

const metaRow = (icon, label, value) =>
  `<p style="color:#333;font-size:15px;margin:8px 0;line-height:1.5;"><strong style="color:#023e8a;">${icon} ${label}:</strong> ${value}</p>`;

const emailHtml = `
<div style="font-family:'Helvetica Neue',Arial,sans-serif;max-width:660px;margin:0 auto;background:#f8fafc;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(105deg,#023e8a,#0077b6);padding:26px 28px;border-radius:10px 10px 0 0;text-align:center;">
    <h1 style="color:#fff;margin:0;font-size:26px;font-family:Georgia,serif;">🌴 Your Tropical Itinerary</h1>
    <p style="color:rgba(255,255,255,0.8);margin:6px 0 0;font-size:14px;">Generated by Voyage Genie · ${tierBadge}</p>
  </div>
  <div style="background:#fff;padding:28px;border-radius:0 0 10px 10px;border:1px solid #e2e8f0;border-top:none;">
    <h2 style="color:#023e8a;font-size:18px;margin:0 0 16px;border-bottom:2px solid #eaf4fb;padding-bottom:10px;">Trip Overview</h2>
    ${metaRow('📍','Destination', destination)}
    ${metaRow('✈️','Departing from', departure)}
    ${metaRow('📅','Dates', travelDates)}
    ${metaRow('🧳','Trip Type', tripType)}
    ${paceLabel ? metaRow('⚡','Travel Pace', paceLabel) : ''}
    ${metaRow('⭐','Plan Tier', tierBadge)}
    ${metaRow('👥','Group Size', groupSize)}
    ${metaRow('💵','Budget', '$'+budget+' USD')}
    ${specialOccasion ? metaRow('🎉','Special Occasion', specialOccasion) : ''}
    ${anniversaryUpgrade ? metaRow('💍','Romantic Upgrade', 'Requested') : ''}
    ${dietaryNeeds ? metaRow('🍽️','Dietary Needs', dietaryNeeds) : ''}
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:20px 0;">
    <h3 style="color:#023e8a;font-size:16px;margin:0 0 14px;">Your Itinerary</h3>
    <div style="background:#f8fafc;padding:20px;border-radius:8px;font-size:14px;line-height:1.7;color:#1e293b;border:1px solid #e2e8f0;">
      ${itineraryContent}
    </div>
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0 16px;">
    <p style="color:#64748b;font-size:12px;text-align:center;margin:0;">
      Generated by <strong>Voyage Genie</strong> 🌟 &nbsp;|&nbsp; Plan Less, Explore More
    </p>
  </div>
</div>`;

const sessionId = [Date.now().toString(36), Math.random().toString(36).slice(2,7)].join('-');
const subject   = `Your ${tierBadge} Tropical Itinerary for ${destination} – Voyage Genie`;

const formData = {
  destination, departure, startDate: $json.startDate||'', endDate: $json.endDate||'',
  flexDates, tripType, travelPace, budgetTier, budget, groupSize,
  dayActivity:       $json.dayActivity       || [],
  nightActivity:     $json.nightActivity     || [],
  ageRange:          $json.ageRange          || [],
  accommodationType: $json.accommodationType || '',
  amenities:         $json.amenities         || [],
  starRating:        $json.starRating        || '',
  specialOccasion, anniversaryUpgrade, dietaryNeeds,
  accessibilityNeeds: $json.accessibilityNeeds || ''
};

return [{ json: {
  sessionId,
  itineraryHtml:   itineraryContent,  // clean AI content for frontend display
  emailHtml:       emailHtml,         // full wrapper for email only
  resolvedEmail:   ($json.email || '').trim(),
  resolvedSubject: subject,
  resolvedMessage: emailHtml,
  formData
}}];

// ── Node: Trigger Email Workflow — Retry-safe email dispatch ──

const EMAIL_WEBHOOK = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const MAX_RETRIES   = 2;
const RETRY_DELAY   = 1500;

const payload = {
  resolvedEmail:   $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage,
};

// Skip silently if no email address was provided
if (!payload.resolvedEmail || payload.resolvedEmail === '') {
  return $input.all();
}

const sleep = (ms) => new Promise(r => setTimeout(r, ms));

let lastError;
for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
  try {
    await $http({
      method:  'POST',
      url:     EMAIL_WEBHOOK,
      body:    payload,
      headers: { 'Content-Type': 'application/json' },
    });
    return $input.all();
  } catch (err) {
    lastError = err;
    if (attempt < MAX_RETRIES) await sleep(RETRY_DELAY);
  }
}

// All retries exhausted — log and continue (email is non-critical)
console.error(`Email delivery failed after ${MAX_RETRIES} attempts: ${lastError?.message}`);
return $input.all();

return [{ json: {
  sessionId:     $json.sessionId,
  redirectUrl:   $json.redirectUrl,
  itineraryData: $json.itineraryData,
  itineraryHtml: $json.itineraryHtml,
  emailHtml:     $json.emailHtml
} }];

// ── Node: Retrieve Itinerary — Return 404 (not yet persisted) ─
// Phase 3: replace this with a Supabase SELECT by sessionId
const sessionId = $json.query?.sessionId || 'unknown';
return [{ json: {
  error: 'Itinerary persistence not yet implemented.',
  hint:  'Connect this node to Supabase to fetch by sessionId.',
  sessionId
}}];

let method = $json.method;
if (!method) {
  method = $json.headers?.[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// ── Node: Prepare New Suggestion — Alternative destination AI call

const body = $json.body || $json;

const destination = body.destination || 'unknown';
const budget      = body.budget      || '0';
const tripType    = body.tripType    || 'Not specified';
const startDate   = body.startDate   || '';
const endDate     = body.endDate     || '';

const prompt = `The user is currently planning a trip to ${destination} with a budget of $${budget} for a ${tripType} trip${startDate ? ` from ${startDate} to ${endDate}` : ''}.

Suggest 3 alternative tropical destinations that:
- Have similar weather and beach quality
- Fit within the same budget range
- Suit a ${tripType} traveler

For each destination provide:
- Destination name and country
- Why it is a great alternative
- Estimated total cost (flights + 7 nights accommodation)
- Best time to visit
- One standout experience unique to that destination
- A booking link or search link (e.g. Skyscanner or Booking.com)

Format each suggestion clearly with a heading and bullet points.`;

return [{ json: { ...body, prompt } }];

// ── Node: Format New Suggestion Response ──────────────────────

const rawContent = $node['OpenAI New Suggestion'].json?.message?.content;

if (!rawContent || rawContent.trim() === '') {
  throw new Error('OpenAI New Suggestion returned empty content.');
}

const sessionId = [
  Date.now().toString(36),
  Math.random().toString(36).slice(2, 7)
].join('-');

return [{ json: {
  sessionId,
  suggestions: rawContent.trim(),
  suggestionsHtml: rawContent.trim().replace(/\n/g, '<br>')
}}];
